package com.g4t0xx.forge;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.nio.file.*;import java.io.*;
public class ActionLedgerTest {
 @Test public void repeatedWriteDoesNotReplay()throws Exception{Path tmp=Files.createTempDirectory("forge-ledger");ActionLedger l=new ActionLedger(tmp.resolve("workspace").toFile(),tmp.resolve("ledger.json").toFile());JSONObject a=Json.obj("action","write_file","path","hello.txt","content","hello","expected_sha256","missing");assertFalse(l.perform(a).getBoolean("reused"));ActionLedger restored=new ActionLedger(tmp.resolve("workspace").toFile(),tmp.resolve("ledger.json").toFile());assertTrue(restored.perform(a).getBoolean("reused"));assertEquals(1,restored.completed().length());}
 @Test public void rejectsConcurrentModificationAndEscape()throws Exception{Path tmp=Files.createTempDirectory("forge-ledger");ActionLedger l=new ActionLedger(tmp.resolve("workspace").toFile(),tmp.resolve("ledger.json").toFile());l.perform(Json.obj("action","write_file","path","hello.txt","content","first","expected_sha256","missing"));try{l.perform(Json.obj("action","write_file","path","hello.txt","content","overwrite","expected_sha256","missing"));fail("must reject stale hash");}catch(IOException expected){}try{l.perform(Json.obj("action","read_file","path","../outside.txt"));fail("must reject escape");}catch(IOException expected){}}
 @Test public void existingHashAllowsSafeUpdate()throws Exception{Path tmp=Files.createTempDirectory("forge-ledger");ActionLedger l=new ActionLedger(tmp.resolve("workspace").toFile(),tmp.resolve("ledger.json").toFile());l.perform(Json.obj("action","write_file","path","note.txt","content","first","expected_sha256","missing"));String hash=l.perform(Json.obj("action","read_file","path","note.txt")).getString("sha256");l.perform(Json.obj("action","write_file","path","note.txt","content","second","expected_sha256",hash));assertEquals("second",new String(Files.readAllBytes(tmp.resolve("workspace/note.txt")),java.nio.charset.StandardCharsets.UTF_8));}
}
